#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define LINE_MAX 2048
#define BUF_MAX  1024

static void url_decode(const char *src, size_t len, char *dst)
{
    size_t i = 0, j = 0;
    while (i < len) {
        char c = src[i];
        if (c == '+') {
            dst[j++] = ' ';
            i++;
        } else if (c == '%' && i + 2 < len && isxdigit((unsigned char)src[i+1]) && isxdigit((unsigned char)src[i+2])) {
            char hi = src[i+1];
            char lo = src[i+2];
            int v = (isdigit((unsigned char)hi) ? hi - '0' : (tolower((unsigned char)hi) - 'a' + 10));
            v = v * 16 + (isdigit((unsigned char)lo) ? lo - '0' : (tolower((unsigned char)lo) - 'a' + 10));
            dst[j++] = (char)v;
            i += 3;
        } else {
            dst[j++] = c;
            i++;
        }
    }
    dst[j] = '\0';
}

int main(void)
{
    static char line[LINE_MAX];
    static char key[BUF_MAX];
    static char val[BUF_MAX];

    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    size_t pos = 0;
    size_t start = 0;
    int have_eq = 0; // 0 = parsing key, 1 = parsing value

    while (1) {
        char c = line[pos];
        if (c == '\n' || c == '\r' || c == '\0') {
            if (have_eq) {
                url_decode(line + start, pos - start, val);
            } else {
                url_decode(line + start, pos - start, key);
                val[0] = '\0';
                printf("%s=%s\n", key, val);
                break;
            }
            printf("%s=%s\n", key, val);
            break;
        }
        if (c == '=' && !have_eq) {
            url_decode(line + start, pos - start, key);
            start = pos + 1;
            have_eq = 1;
        } else if (c == '&') {
            if (have_eq) {
                url_decode(line + start, pos - start, val);
            } else {
                url_decode(line + start, pos - start, key);
                val[0] = '\0';
                printf("%s=%s\n", key, val);
                start = pos + 1;
                have_eq = 0;
                pos++;
                continue;
            }
            printf("%s=%s\n", key, val);
            start = pos + 1;
            have_eq = 0;
        }
        pos++;
    }
    return 0;
}
